type ownerBridgeDenyLoader struct{}

// Use the evaluator's documented ECMAScript engine, preserving the accepted
// regex syntax. Patterns come only from the fixed embedded schemas.
type ownerBridgeRegexp regexp2.Regexp

func (r *ownerBridgeRegexp) String() string { return (*regexp2.Regexp)(r).String() }
func (r *ownerBridgeRegexp) MatchString(value string) bool {
	matched, err := (*regexp2.Regexp)(r).MatchString(value)
	return err == nil && matched
}
func compileOwnerBridgeRegexp(pattern string) (jsonschema.Regexp, error) {
	r, err := regexp2.Compile(pattern, regexp2.ECMAScript)
	if err != nil {
		return nil, bridgeError("schema_pattern_invalid")
	}
	r.MatchTimeout = 50 * time.Millisecond
	return (*ownerBridgeRegexp)(r), nil
}

func (ownerBridgeDenyLoader) Load(string) (any, error) {
	return nil, bridgeError("schema_resource_denied")
}

var ownerBridgeSchemaOnce sync.Once
var ownerBridgeCompiled map[string]*jsonschema.Schema
var ownerBridgeSchemaFailure error

func compileOwnerBridgeSchemas() {
	compiler := jsonschema.NewCompiler()
	compiler.DefaultDraft(jsonschema.Draft2020)
	compiler.UseRegexpEngine(compileOwnerBridgeRegexp)
	compiler.UseLoader(ownerBridgeDenyLoader{})
	for urn, raw := range ownerBridgeSchemaResources {
		value, err := jsonschema.UnmarshalJSON(bytes.NewReader([]byte(raw)))
		if err != nil {
			ownerBridgeSchemaFailure = bridgeError("schema_invalid")
			return
		}
		if compiler.AddResource(urn, value) != nil {
			ownerBridgeSchemaFailure = bridgeError("schema_invalid")
			return
		}
	}
	ownerBridgeCompiled = map[string]*jsonschema.Schema{}
	for _, kind := range []string{"host-owner-status-request", "host-owner-status-reply", "startup-status-observation"} {
		schema, err := compiler.Compile("urn:agentmux:contract:1:" + kind)
		if err != nil {
			ownerBridgeSchemaFailure = bridgeError("schema_invalid")
			return
		}
		ownerBridgeCompiled[kind] = schema
	}
}
func validateOwnerBridgeJSON(raw []byte, kind string, maxBytes int) error {
	// Preserve duplicate-key, trailing, UTF8, surrogate and depth guards before
	// handing the number-preserving parse to the schema library.
	var ignored map[string]any
	if protocol.DecodeClosedJSON(raw, &ignored, maxBytes) != nil {
		return bridgeError("shape_invalid")
	}
	ownerBridgeSchemaOnce.Do(compileOwnerBridgeSchemas)
	if ownerBridgeSchemaFailure != nil {
		return ownerBridgeSchemaFailure
	}
	schema, ok := ownerBridgeCompiled[kind]
	if !ok {
		return bridgeError("schema_invalid")
	}
	value, err := jsonschema.UnmarshalJSON(bytes.NewReader(raw))
	if err != nil || schema.Validate(value) != nil {
		return bridgeError("shape_invalid")
	}
	return nil
}
